select ib.file_name, ib.row_count, ib.created_at, count(e.id) as evaluations_linked
from public.import_batches ib
left join public.evaluations e on e.import_batch_id = ib.id
where ib.file_name = 'rstw-evaluations-clean.xlsx'
group by ib.id, ib.file_name, ib.row_count, ib.created_at;

select title, response_count, average_score from public.training_stats
where title ilike '%RSTW%' or title ilike '%ROBOTICS%' or title ilike '%TechUp%'
order by response_count desc
limit 20;
